function img(src,alt,extra=""){
 const isCoffee=/coffee|nitro|espresso/i.test(src+" "+alt);
 const isPastry=/pastry|breakfast|toast/i.test(src+" "+alt);
 const isBowl=/bowl|dinner|noodles/i.test(src+" "+alt);
 const emoji=isCoffee?"☕":isPastry?"🥐":isBowl?"🍜":"🥪";
 const subtitle=isCoffee?"A LITTLE COFFEE MOMENT":isPastry?"YOUR NEXT FAVORITE BITE":isBowl?"A TABLE WORTH SHARING":"LUNCH PLANS, SORTED";
 const fallback=src===PHOTO.nitroCoffee?"https://cdn.corner.inc/place-photo/71915bbb-7012-4da5-9028-971e6dba4767.jpeg":src===PHOTO.poppyBakery?"https://images.pexels.com/photos/3639538/pexels-photo-3639538.jpeg?auto=compress&cs=tinysrgb&w=1000":"";
 return '<div class="photo-surface" role="img" aria-label="'+esc(alt)+'"><div class="photo-backdrop"><span class="photo-stamp">FUSE / FOOD</span><span class="photo-plate">'+emoji+'</span><span class="photo-caption">'+subtitle+'</span></div><img class="actual-photo" src="'+esc(src)+'" '+(fallback?'data-photo-backup="'+esc(fallback)+'"':'')+' alt="" loading="lazy" '+extra+'></div>';
}
document.addEventListener("error",event=>{
 const node=event.target;
 if(node&&((node.tagName==="VIDEO"&&node.classList.contains("reel-video"))||(node.tagName==="SOURCE"&&node.parentElement?.classList.contains("reel-video")))){const vid=node.tagName==="SOURCE"?node.parentElement:node;vid.hidden=true;vid.closest(".reel-stage")?.classList.add("video-failed");return;}
 if(node&&node.tagName==="IMG"&&node.classList.contains("actual-photo")){
   if(node.dataset.photoBackup&&!node.dataset.photoBackupAttempted){node.dataset.photoBackupAttempted="true";node.src=node.dataset.photoBackup;return;}
   node.hidden=true;
   node.closest(".photo-surface")?.classList.add("image-failed");
 }
},true);
