function render(){nav();const screens={explore,forYou,friends,visits,content,profile,referrals,overview,create,creators,videos};let html;if(state.detail?.type==="offer")html=offerDetail(state.detail.id);else if(state.detail?.type==="claimed")html=claimedScreen(state.detail.id);else if(state.detail?.type==="friend")html=friendScreen(state.detail.id);else if(state.detail?.type==="friend-profile")html=friendProfile(state.detail.id);else if(state.detail?.type==="restaurant")html=restaurantDetail(state.detail.id);else if(state.detail?.type==="video")html=videoDetail(state.detail.id);else if(state.detail?.type==="campaign")html=campaignResult(state.detail.id);else if(state.detail?.type==="qr")html=qrScreen(state.detail.id);else if(state.role==="student"&&state.tab==="profile"&&window.FuseSocial?.enabled)html=window.FuseSocial.renderProfile();else if(state.role==="student"&&state.tab==="friends"&&window.FuseSocial?.enabled)html=window.FuseSocial.renderFriends();else html=screens[state.tab]();$("#content").innerHTML=html;if(state.tab==="explore"&&state.mapVisible&&!state.detail)requestAnimationFrame(initMap);if(state.tab==="profile"&&state.role==="student")requestAnimationFrame(updateTikTokBadge);if(state.tab==="content"&&state.role==="student"&&state.contentSection==="posts")requestAnimationFrame(loadTikTokFeed);if(state.detail?.type==="qr")requestAnimationFrame(drawQR);}
