function initMap(){const host=$("#mapFrame");if(!host)return;if(!window.L){host.innerHTML='<div class="map-static">Map tiles unavailable. Select a venue below.</div>';return;}const map=window.L.map(host,{scrollWheelZoom:false}).setView([41.835,-71.418],13);window.L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap contributors",maxZoom:19}).addTo(map);EXPLORE_CAMPAIGNS.map(campaign).filter(Boolean).forEach(c=>{const b=business(c.businessId);if(!Number.isFinite(b.lat)||!Number.isFinite(b.lng))return;const pin=window.L.circleMarker([b.lat,b.lng],{radius:9,color:"#fff",weight:3,fillColor:"#c7fb43",fillOpacity:1}).addTo(map);pin.bindTooltip(b.name+" · "+available(c)+" spots");pin.on("click",()=>goDetail("offer",c.id));});window.L.circleMarker([41.8437,-71.4378],{radius:7,color:"#fff",weight:2,fillColor:"#22376e",fillOpacity:1}).bindTooltip("Providence College · reference only").addTo(map);setTimeout(()=>map.invalidateSize(),100);}
function offerDetail(id){const c=campaign(id);if(!c)return explore();const b=business(c.businessId);const my=state.claims.find(x=>x.campaignId===id&&x.studentId===state.activeStudent&&!expired(x));const blocked=state.overdueSimulation&&state.claims.some(x=>x.studentId===state.activeStudent&&!videoForClaim(x.id)&&x.status==="overdue");return '<div class="hero-image">'+img(c.image,c.title)+btn("‹","back","","back")+'<span class="pill floating">'+esc(b.name)+' · '+esc(c.neighborhood)+'</span></div><section class="detail-content"><p class="eyebrow">THE OFFER · '+esc(b.name)+'</p><h1 class="page-title">'+esc(b.name)+'</h1><p class="offer-detail-subtitle">'+esc(c.title)+'</p>'+offerChips(c)+'<div class="exchange"><strong>'+esc(c.comp==="visit"?"Your visit is covered.":c.reward+" for your post.")+'</strong><p>'+esc(c.comp==="visit"?"Your lunch is covered. Post one original video within 48 hours of your visit.":"Your visit is covered. Post one original video within 48 hours of your visit.")+'</p></div><div class="detail-line"><b>What to try</b><span>'+esc(c.description)+'</span></div><div class="detail-line"><b>Visit window</b><span>'+esc(c.window)+'</span></div><div class="detail-line"><b>Visit within</b><span>7 days after claiming. Show your Fuse QR at the restaurant.</span></div><div class="detail-line"><b>Post deadline</b><span>'+esc(c.deadline)+'</span></div><div class="detail-line"><b>Your post</b><span>'+esc(c.post)+'</span></div><div class="detail-group"><h3>Restaurant video brief</h3>'+(c.hook?'<div class="brief-detail-grid"><div><b>Suggested hook</b><p>'+esc(c.hook)+'</p></div><div><b>Must-show shots</b><p>'+esc(c.shots)+'</p></div><div><b>Key details</b><p>'+esc(c.talkingPoints)+'</p></div><div><b>Creative freedom</b><p>'+esc(c.creativeFreedom||"Honest review, in your own words.")+'</p></div><div><b>Platform and timing</b><p>'+esc(c.videoFormat||"TikTok or Reel")+' · '+esc(c.deadline)+'</p></div></div>':'<p>'+esc(c.brief)+'</p>')+'</div><p class="fine-print">Your video goes on your own TikTok or Instagram account. Each creator must post their own video and submit their own link. Be honest and disclose your covered meal or drink.</p><div class="sticky-actions">'+(my?btn("Go to my visit →","visits","","button full"):blocked?'<div class="reminder">Submit your overdue video before claiming another offer.</div>'+btn("Go to my visits","visits","","button full"):available(c)===0?'<button class="button full" disabled>All spots claimed</button>':!me().approved?btn("Apply as a creator first →","profile","","button full"):(c.duo&&available(c)>=2?btn("Tag a Fuse friend & claim 2 spots","claim-with-friend",id,"button full")+btn("Or claim solo","claim",id,"button secondary full"):btn("Claim a spot","claim",id,"button full")))+btn("Back to Explore","back","","button secondary full")+'</div></section>'}
function claim(id,who=state.activeStudent){const c=campaign(id);if(!c||c.status!=="open"||available(c)<=0){toast("There are no spots left.");return null}if(state.claims.some(x=>x.campaignId===id&&x.studentId===who&&!expired(x))){toast("This student already has a spot.");return null}const timestamp=Date.now(),ob={id:uid(),campaignId:id,studentId:who,status:"claimed",review:who==="maya"?"approved":"pending",claimedAt:new Date(timestamp).toISOString(),expiresAt:new Date(timestamp+7*DAY).toISOString(),visitDate:new Date(timestamp+7*DAY).toISOString(),redemptionCode:"FG-"+Math.random().toString(36).slice(2,10).toUpperCase()};state.claims.push(ob);persist();return ob}
