formModal("Tag your Fuse friend",'<p class="small muted">Each creator gets their own covered meal and owes one original video.</p>'+field("fuse","Friend’s Fuse username","@leo.pvd")+'<p class="help">Try @leo.pvd for this demo.</p>',"Reserve two spots",data=>{
const h=String(data.get("fuse")||"").trim().toLowerCase(),friend=state.students.find(u=>u.fuseHandle?.toLowerCase()===h);
if(!friend)return toast("No matching Fuse demo username. Try @leo.pvd.");
if(friend.id===state.activeStudent)return toast("Tag a different creator.");
if(available(c)<2||state.claims.some(x=>x.campaignId===c.id&&(x.studentId===friend.id||x.studentId===state.activeStudent)))return toast("One of you already claimed, or two spots are no longer open.");
const mine=claim(id,state.activeStudent);if(!mine)return;
const invited=claim(id,friend.id);if(!invited){state.claims=state.claims.filter(x=>x.id!==mine.id);persist();return;}
invited.status="invited";invited.invitedBy=state.activeStudent;mine.taggedFriend=friend.fuseHandle;
persist();closeModal();goDetail("claimed",mine.id);toast("Two spots reserved. Your friend can accept in My visits.");
});
