function visitCard(a){const c=campaign(a.campaignId),b=business(c.businessId),v=videoForClaim(a.id),pair=claimsFor(c.id),submitted=pair.filter(x=>videoForClaim(x.id)).length;const isExpired=expired(a);
return '<article class="visit-card"><div class="visit-title"><div><p class="eyeline">'+esc(b.name)+' · '+esc(c.neighborhood)+'</p><h3>'+esc(c.title)+'</h3></div>'+tag(a.redeemedAt?"Redeemed":isExpired?"Expired":a.status==="invited"?"Invited":v?"Posted":"Claimed",a.redeemedAt?"good":isExpired?"late":"waiting")+'</div>'+
 '<div class="visit-deadline"><span>◷ Visit window</span><strong>'+(a.redeemedAt?"Checked in ✓":isExpired?"Expired":daysLeft(a)+" day"+(daysLeft(a)===1?"":"s")+" left")+'</strong></div>'+
 '<p class="small muted">Visit by '+esc(expiryLabel(a))+' · '+esc(c.window)+'</p>'+
 (a.status==="invited"?'<div class="notice">Your friend tagged you. Accept before visiting.</div>'+btn("Accept invitation","accept-tagged",a.id,"button full"):a.redeemedAt?'<div class="notice green">✓ Your QR was redeemed by the restaurant. Post within 48 hours of your visit.</div>':isExpired?'<div class="notice red">This claim expired before check-in.</div>':btn("Show my meal QR code →","qr",a.id,"button full"))+
 '<div class="progress-track"><i style="width:'+Math.round(100*submitted/Math.max(1,pair.length))+'%"></i></div><p class="tiny-muted">'+submitted+' of '+pair.length+' individual posts submitted</p>'+
 (v?btn("See my video →","restaurant",b.id,"button secondary full"):a.redeemedAt?submitForm(a):'<p class="fine-print">Video submission unlocks after restaurant QR check-in.</p>')+'</article>';}
function submitForm(a){return '<form data-form="post" data-id="'+esc(a.id)+'"><div class="form-group"><label class="label" for="post-'+esc(a.id)+'">Paste your TikTok or Instagram Reel link</label><input id="post-'+esc(a.id)+'" class="field" name="url" type="url" required placeholder="https://www.tiktok.com/@you/video/..." /></div><button class="button full" type="submit">Submit my video →</button></form>'}
function content(){return '<div class="content-shell">'+heading("YOUR CREATOR HUB","My Content","Your visits and restaurant videos in one place.")+'<div class="social-tabs"><button type="button" data-action="content-section" data-id="visits" class="'+(state.contentSection==="visits"?"active":"")+'">My Visits</button><button type="button" data-action="content-section" data-id="posts" class="'+(state.contentSection==="posts"?"active":"")+'">My Posts</button></div>'+(state.contentSection==="visits"?visits():postsContent())+'</div>';}
function postsContent(){const groups=state.businesses.map(b=>({b,posts:videosForMe().filter(v=>campaign(v.campaignId)?.businessId===b.id)})).filter(g=>g.posts.length);return '<section class="page">'+heading("YOUR CREATOR PORTFOLIO","My content","What have I posted for each restaurant, and how did those videos do?")+'<div class="metric-row"><div class="metric-panel"><strong>'+videosForMe().length+'</strong><span>Published videos</span></div><div class="metric-panel"><strong>'+fmt(videosForMe().reduce((t,v)=>t+(v.views||0),0))+'</strong><span>Total reported video views</span></div></div>'+personalVideoCards()+(groups.length?groups.map(g=>restaurantCard(g.b,g.posts)).join(""):"")+'<div class="section-heading"><h2>My recent TikToks</h2><span>From connected account</span></div><div id="tiktokFeed" class="panel"><p class="small muted">Connect TikTok from Profile to show your own public posts here. Campaign submissions remain separate until you select a video for a visit.</p></div>'+'<div class="notice">Seeded analytics are demo data, last updated Nov 10, 2026. New submissions show “Stats pending.” Your totals exclude friends’ videos.</div></section>'}
function restaurantCard(b,posts){return '<article class="restaurant-card"><div class="restaurant-photo">'+img(b.photo,b.name)+'</div><div style="min-width:0;flex:1"><p class="eyeline">'+esc(b.neighborhood)+'</p><h3>'+esc(b.name)+'</h3><p class="tiny-muted">'+posts.length+' published post'+(posts.length===1?"":"s")+' · '+fmt(posts.reduce((sum,v)=>sum+(v.views||0),0))+' views</p>'+btn("View my videos →","restaurant",b.id,"button text")+'</div></article>'}
function restaurantDetail(id){const b=business(id),posts=videosForMe().filter(v=>campaign(v.campaignId)?.businessId===id).reverse();return '<section class="page">'+btn("← My content","content","","button text")+heading("MY RESTAURANT HISTORY",esc(b.name),esc(b.neighborhood)+" · "+posts.length+" of my published videos across "+new Set(posts.map(p=>p.campaignId)).size+" campaigns.")+'<div class="metric-row"><div class="metric-panel"><strong>'+posts.length+'</strong><span>My posts</span></div><div class="metric-panel"><strong>'+fmt(posts.reduce((t,v)=>t+(v.views||0),0))+'</strong><span>My total views</span></div></div>'+posts.map(v=>videoCard(v,false)).join("")+'<div class="notice">My statistics include only my own posts. Demo analytics last updated Nov 10, 2026; new posts show Stats pending.</div></section>'}
function videoCard(v,showCreator=false){const c=campaign(v.campaignId),s=student(v.studentId),pending=v.views===null;return '<article class="video-card"><div class="flex align-start"><div class="video-thumb">'+img(v.image,v.title)+'<span class="play">▶</span></div><div style="min-width:0;flex:1"><p class="eyeline">'+esc(v.platform)+' · '+esc(v.date)+'</p><h4>'+esc(v.title)+'</h4>'+(showCreator?'<p class="tiny-muted">By '+esc(s?.name||"Creator")+' · '+esc(s?.handle||"")+'</p>':"")+'<div class="stats-list">'+(pending?'<span>Stats pending</span>':'<span>▶ '+fmt(v.views)+' views</span><span>♥ '+fmt(v.likes)+'</span><span>☷ '+fmt(v.comments)+'</span><span>◇ '+fmt(v.saves)+'</span>')+'</div>'+btn("View video →","video",v.id,"button text")+'</div></div><p class="brief"><b>Campaign:</b> '+esc(c.title)+' · '+esc(c.brief)+'</p><p class="tiny-muted">'+(v.demo?"Demo data · Stats last updated "+esc(v.updated):"Newly submitted · Stats pending")+'</p></article>'}
function videoDetail(id){const v=state.videos.find(v=>v.id===id);if(!v)return content();const c=campaign(v.campaignId),s=student(v.studentId);return '<section class="page">'+btn("← Back","back","","button text")+heading("PUBLISHED VIDEO",esc(v.title),esc(s.name)+" · "+esc(v.platform)+" · "+esc(v.date))+'<div class="video-preview">'+img(v.image,v.title)+'<div class="play">▶</div></div><p class="preview-caption">Thumbnail preview only. The original video opens on '+esc(v.platform)+'. For the hackathon, seeded video URLs are sample platform links.</p><div class="metric-row">'+[["Views",v.views],["Likes",v.likes],["Comments",v.comments],["Saves",v.saves]].map(([k,val])=>'<div class="metric-panel"><strong>'+(val===null?"—":fmt(val))+'</strong><span>'+k+'</span></div>').join("")+'</div><div class="panel"><p class="eyeline">CAMPAIGN BRIEF</p><h3>'+esc(c.title)+'</h3><p class="small muted">'+esc(c.brief)+'</p></div><a class="button full" target="_blank" rel="noopener noreferrer" href="'+esc(v.url)+'">Open original post ↗</a><p class="fine-print" style="margin-top:13px">'+(v.demo?"Sample analytics are demo data · Last updated "+esc(v.updated):"Stats pending. Analytics are not automatically fetched from TikTok or Instagram.")+'</p></section>'}
function profile(){const u=me();return '<section class="page">'+heading("YOUR CREATOR PROFILE",esc(u.name),"Your Fuse username is "+esc(u.fuseHandle||"@nevepalmeri")+".")+
 '<div class="panel profile-person"><div class="profile-avatar">NP<span>✳</span></div><div><h3>'+esc(u.name)+'</h3><p class="small muted">'+esc(u.school)+'</p><p class="small muted">Fuse: '+esc(u.fuseHandle||"—")+'</p><p class="small muted">TikTok: '+esc(u.handle)+'</p></div></div>'+
 '<div class="panel"><div class="flex between"><h3>Your TikTok account</h3><span id="tiktokBadge" class="status waiting">Not connected</span></div><p class="small muted">Authorize TikTok to display your recent public videos on Fuse. Once connected, your posts can show in My content.</p>'+
 btn("Connect TikTok account →","connect-tiktok","","button full")+'<p class="fine-print">Connecting requires TikTok Login Kit and approved video access. We will never ask for your TikTok password.</p></div>'+
 '<div class="panel"><h3>Creator details</h3><p class="small muted">'+esc(u.history)+'</p>'+tag(u.approved?"Approved creator":"Pending review",u.approved?"good":"waiting")+btn("Edit profile","edit-profile","","button secondary full card-action")+'<div style="margin-top:10px">'+btn("Switch demo creator →","switch-student","","button secondary full")+'</div></div>'+
 '<div class="panel"><h3>Bring your friends.</h3><p class="small muted">Tag friends on duo offers, or invite new creators to Fuse.</p>'+btn("Open referral program →","referrals","","button full")+'</div><p class="fine-print">FuseGenerated is independent of Providence College.</p></section>';
}
function referrals(){const n=state.referrals.length;return '<section class="page">'+heading("SHARE YOUR CITY","Refer a friend.","Invite local creators and discover more places together.")+'<div class="referral-hero"><p class="eyebrow">YOUR REFERRAL CODE</p><h2>'+esc(state.referralCode)+'</h2><p>Share your unique demo code with a friend.</p>'+btn("Copy invite","copy-referral","","button full")+'</div><div class="metric-row"><div class="metric-panel"><strong>'+n+'</strong><span>Friends joined · demo</span></div><div class="metric-panel"><strong>'+Math.min(n,2)+'/2</strong><span>Toward early access</span></div></div><div class="panel"><h3>How it works</h3><p class="small muted">Share your code. A friend joins with their own account. Two verified referrals will unlock early previews of new offers when the pilot launches.</p>'+btn("Preview friend joining →","referral-join","","button secondary full")+'</div><div class="notice">Referral tracking and rewards are demo-only. No real invite is sent.</div></section>';}
function businessSwitcher(){return '<div class="panel"><label class="label" for="businessSelect">Demo as this restaurant</label><select class="field" id="businessSelect">'+state.businesses.map(b=>'<option value="'+esc(b.id)+'" '+(state.selectedBusiness===b.id?"selected":"")+'>'+esc(b.name)+'</option>').join("")+'</select></div>';}
function redeemPanel(){const b=business(state.selectedBusiness)||business("nitro"),n=state.claims.filter(a=>campaign(a.campaignId)?.businessId===b.id&&a.redeemedAt).length;return '<div class="qr-redeem-panel"><p class="eyebrow">IN-STORE REDEMPTION</p><h3>Scan their pass. Cover the meal.</h3><p class="small">Ask the creator to show their Fuse QR. Verify their visit, then mark the meal covered.</p><form data-form="redeem"><label class="label" for="redeemInput">Scan or enter their QR code</label><input class="field" name="code" id="redeemInput" placeholder="FG-XXXXXXXX" required autocomplete="off"/><button class="button full" type="submit">Verify & redeem visit</button></form>'+btn("Scan with camera","scan-qr","","button secondary full card-action")+'<p class="fine-print">'+n+' redeemed pass'+(n===1?"":"es")+' for '+esc(b.name)+'. This is a demo, not a real meal authorization.</p></div>';}
function redeemCode(input){const code=String(input||"").trim().replace(/^FUSE-DEMO\|/i,"").toUpperCase(),a=state.claims.find(x=>redemptionCode(x).toUpperCase()===code);if(!a)return toast("Code not found in this demo browser.");const c=campaign(a.campaignId);if(!c||c.businessId!==state.selectedBusiness)return toast("That QR is for a different restaurant.");if(a.status==="invited")return toast("The invited friend must accept first.");if(a.redeemedAt)return toast("This pass has already been redeemed.");if(expired(a))return toast("This pass expired after seven days.");a.redeemedAt=new Date().toISOString();a.status="visited";persist();render();toast("✓ "+student(a.studentId).name+" checked in. "+c.reward+".");}
let qrStream=null,qrScanning=false;
function stopQrScan(){qrScanning=false;if(qrStream){qrStream.getTracks().forEach(t=>t.stop());qrStream=null;}closeModal();}
async function scanQR(){if(!navigator.mediaDevices?.getUserMedia||typeof BarcodeDetector==="undefined")return toast("QR scanning is not supported here. Enter the code instead.");try{const detector=new BarcodeDetector({formats:["qr_code"]});qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"},audio:false});$("#modalTitle").textContent="Scan Fuse QR";$("#modalContent").innerHTML='<video autoplay playsinline muted id="qrVideo" style="width:100%;border-radius:15px"></video>'+btn("Stop scanner","stop-qr","","button secondary full");$("#modal").showModal();const video=$("#qrVideo");video.srcObject=qrStream;await video.play();qrScanning=true;const loop=async()=>{if(!qrScanning)return;try{const codes=await detector.detect(video);if(codes.length){const raw=codes[0].rawValue;stopQrScan();redeemCode(raw);return;}}catch{}if(qrScanning)requestAnimationFrame(loop);};requestAnimationFrame(loop);}catch{stopQrScan();toast("Camera unavailable. Enter the QR pass code.");}}
function overview(){const current=business(state.selectedBusiness)||business("nitro"),clips=videosForBusiness(current.id),total=state.claims.filter(a=>campaign(a.campaignId)?.businessId===current.id).length;
return '<section class="page">'+heading("YOUR RESTAURANT","Business overview","See exactly what your creator visits produced.")+businessSwitcher()+redeemPanel()+
'<div class="metric-row"><div class="metric-panel"><strong>'+total+'</strong><span>Creator claims</span></div><div class="metric-panel"><strong>'+clips.length+'</strong><span>Submitted posts</span></div></div>'+
'<div class="section-heading"><h2>Campaign results</h2><span>Tap to inspect</span></div>'+state.campaigns.filter(c=>c.businessId===current.id).map(resultCard).join("")+
'<div class="panel"><h3>$0 Fuse platform fee.</h3><p class="small muted">In this pilot, the restaurant only covers the agreed meals or drinks for up to three creators. Each creator shows a QR pass to redeem their offer, then submits one original TikTok or Reel. No guaranteed customers or rankings.</p></div>'+
btn("Create an offer →","create","","button full")+'</section>';}
function resultCard(c){const claims=claimsFor(c.id),posted=claims.filter(x=>videoForClaim(x.id)),visits=state.customerVisits[c.id]||0;return '<article class="result-card"><div class="flex between"><span class="eyeline">'+esc(c.title)+'</span>'+tag(c.status==="completed"?"Completed":"Open",c.status==="completed"?"good":"waiting")+'</div><h3 class="result-title">'+esc(business(c.businessId).name)+'</h3><div class="counts"><div><strong>'+claims.length+'</strong>claimed</div><div><strong>'+claims.filter(x=>x.status==="visited"||x.status==="posted").length+'</strong>visited</div><div><strong>'+posted.length+'</strong>posted</div><div><strong>'+visits+'</strong>reported visits</div></div><div style="margin-top:14px">'+btn("See campaign results →","campaign",c.id,"button secondary full")+'</div></article>'}
function campaignResult(id){const c=campaign(id),b=business(c.businessId),cl=claimsFor(id),vs=state.videos.filter(v=>v.campaignId===id),reported=state.customerVisits[id]||0;return '<section class="page">'+btn("← Business overview","overview","","button text")+heading("CAMPAIGN RESULTS",esc(c.title),esc(b.name)+" · "+esc(c.neighborhood))+'<div class="metric-row"><div class="metric-panel"><strong>'+cl.length+' / '+c.spots+'</strong><span>Creator spots claimed</span></div><div class="metric-panel"><strong>'+vs.length+'</strong><span>Individual posts submitted</span></div><div class="metric-panel"><strong>'+fmt(vs.reduce((t,v)=>t+(v.views||0),0))+'</strong><span>Video views · demo analytics</span></div><div class="metric-panel"><strong>'+reported+'</strong><span>Customer visits reported by you</span></div></div><div class="report-box"><strong>A customer showed us a post</strong><p>Customer visits reported by you · not verified by FuseGenerated</p>'+btn("+1 customer visit","plus-one",id,"button dark tiny")+'</div><div class="section-heading"><h2>Creator follow-through</h2></div>'+(cl.length?cl.map(a=>'<div class="panel"><div class="flex between"><div><b>'+esc(student(a.studentId)?.name||"Student")+'</b><p class="tiny-muted">'+esc(student(a.studentId)?.handle||"")+'</p></div>'+tag(videoForClaim(a.id)?"Posted":a.status==="visited"?"Visited":a.review==="pending"?"Needs review":"Claimed",videoForClaim(a.id)?"good":"waiting")+'</div>'+(videoForClaim(a.id)?btn("Watch / open video →","video",videoForClaim(a.id).id,"button text"):'<p class="small muted">Post still due · '+esc(c.deadline)+'</p>')+'</div>').join(""):'<div class="empty">No creators have claimed this offer yet.</div>')+'<div class="section-heading"><h2>Submitted videos</h2></div>'+(vs.length?'<div class="panel">'+vs.map(v=>videoCard(v,true)).join("")+'</div>':'<div class="empty">Published videos will appear here as links are submitted.</div>')+'<div class="notice">Video views, likes, comments, and saves are seeded demo data when shown; new links display Stats pending. No guaranteed visits or rankings.</div></section>'}
function create(){return '<section class="page">'+heading("QUICK CAMPAIGN BUILDER","Create an offer","A café owner should be able to finish this between customers.")+'<form data-form="new-offer"><div class="form-group"><label class="label" for="discover">What do you want people in Providence to discover?</label><input class="field" id="discover" name="title" placeholder="Our weekday lunch special" required maxlength="100"></div><div class="form-group"><label class="label" for="businessName">Business name</label><input class="field" id="businessName" name="business" value="Juniper & Rye" required maxlength="85"></div><div class="form-group"><label class="label" for="neighborhood">Neighborhood</label><select class="field" id="neighborhood" name="neighborhood"><option>Elmhurst</option><option>Federal Hill</option><option>College Hill</option><option>Downtown</option><option>Fox Point</option><option>Wayland Square</option></select></div><div class="form-group"><label class="label" for="offer">What does the creator get?</label><input class="field" id="offer" name="reward" placeholder="Lunch for one, up to $15" required maxlength="85"></div><div class="form-group"><label class="label">What is covered for each creator?</label><div class="toggle-pair"><button type="button" class="choice '+(state.offerComp==="visit"?"selected":"")+'" data-action="set-comp" data-id="visit">✳ Cover the visit</button><button type="button" class="choice '+(state.offerComp==="cash"?"selected":"")+'" data-action="set-comp" data-id="visit">☕ Cover food & drink</button></div></div><div class="form-row"><div class="form-group"><label class="label" for="spots">Creator spots</label><input class="field" id="spots" name="spots" type="number" min="3" max="3" value="3" readonly required></div><div class="form-group"><label class="label" for="window">Visit window</label><input class="field" id="window" name="window" value="Weekdays 11 AM–2 PM" required maxlength="80"></div></div><div class="form-group"><label class="label" for="post">What should they post?</label><textarea class="field" id="post" name="post" required maxlength="250">One original TikTok or Reel on their own account within 48 hours of visiting.</textarea></div><div class="brief-builder"><p class="eyebrow">VIDEO CREATIVE BRIEF</p><h3>What should the video show?</h3><p class="small muted">Give concrete instructions without requiring a positive review or scripted endorsement.</p><div class="form-group"><label class="label" for="hook">Suggested opening / hook</label><input class="field" id="hook" name="hook" maxlength="150" required placeholder="Lunch near campus for under $15"></div><div class="form-group"><label class="label" for="shots">Specific shots to capture</label><textarea class="field" id="shots" name="shots" maxlength="600" required placeholder="Storefront, the price on the menu, food close-up, seating"></textarea></div><div class="form-group"><label class="label" for="talkingPoints">Key details to communicate</label><textarea class="field" id="talkingPoints" name="talkingPoints" maxlength="600" required placeholder="Lunch special price, hours, directions from PC"></textarea></div><div class="form-group"><label class="label" for="creativeFreedom">Creator freedom / things to avoid</label><textarea class="field" id="creativeFreedom" name="creativeFreedom" maxlength="500" placeholder="Honest review, no scripted claims; avoid filming other customers"></textarea></div><div class="form-row"><div class="form-group"><label class="label" for="videoFormat">Post format</label><select id="videoFormat" class="field" name="videoFormat"><option>TikTok</option><option>Instagram Reel</option><option>Either</option></select></div><div class="form-group"><label class="label" for="postingTime">Post by</label><select id="postingTime" name="postingTime" class="field"><option>Within 48 hours after visit</option><option>Within 24 hours after visit</option><option>Within 72 hours after visit</option></select></div></div><p class="fine-print">Creators disclose the complimentary visit. Content must reflect their honest experience; a covered meal does not guarantee positive sentiment or views.</p></div><div class="notice">Creators keep their own voice and disclose covered visits. Free pilot: $0 platform fee. Your business covers only the food and drinks promised to three creators. No subscription, listing fee or per-video platform fee.</div><button class="button full" type="submit">Publish demo offer →</button></form></section>'}
function creators(){const at=state.claims.filter(a=>a.review==="pending"||a.review==="approved").slice().reverse();const creatorIds=["maya","leo"];return '<section class="page">'+heading("WHO’S MAKING THE VIDEOS?","Review creators","See examples of local work and whether each creator follows through.")+'<div class="notice">Approving a creator updates this interactive demo only. No real messages are sent.</div>'+creatorIds.map(id=>creatorReview(student(id))).join("")+'<div class="section-heading"><h2>Current claims</h2></div>'+(at.length?at.map(a=>{const s=student(a.studentId),c=campaign(a.campaignId);return '<div class="panel"><div class="flex between"><div><b>'+esc(s.name)+'</b><p class="tiny-muted">'+esc(c.title)+'</p></div>'+tag(a.review==="approved"?"Approved":"Needs approval",a.review==="approved"?"good":"waiting")+'</div>'+(a.review!=="approved"?btn("Approve creator","approve",a.id,"button tiny"):btn("View campaign →","campaign",c.id,"button text"))+'</div>'}).join(""):'<div class="empty">New student claims will appear here.</div>')+'</section>'}
function creatorReview(s){const p1=s.id==="maya"?PHOTO.coffee:PHOTO.city,p2=s.id==="maya"?PHOTO.toast:PHOTO.bowl;return '<article class="creator-card"><div class="flex between"><div><h3>'+esc(s.name)+'</h3><p class="small muted">'+esc(s.school)+' · '+esc(s.handle)+'</p></div>'+tag(s.history,s.id==="maya"?"good":"new")+'</div><div class="preview-row">'+img(p1,"Local content example one")+img(p2,"Local content example two")+'</div><div class="flex between"><span class="tiny-muted">Two local content previews · sample images</span>'+btn("Open samples ↗","samples",s.id,"button text")+'</div>'+(s.id==="leo"?'<div class="notice">First visit · review their local video samples, not follower counts.</div>':"")+'</article>'}
function videos(){const b=business(state.selectedBusiness)||business("nitro"),campaigns=state.campaigns.filter(c=>c.businessId===b.id),total=videosForBusiness(b.id);return '<section class="page">'+heading(esc(b.name).toUpperCase(),"Creator videos","Every video submitted for your restaurant, grouped by campaign.")+'<div class="metric-row"><div class="metric-panel"><strong>'+total.length+'</strong><span>Videos submitted</span></div><div class="metric-panel"><strong>'+fmt(total.reduce((t,v)=>t+(v.views||0),0))+'</strong><span>Demo video views</span></div></div>'+campaigns.map(c=>{const posts=state.videos.filter(v=>v.campaignId===c.id);return '<div class="section-heading"><h2 style="font-size:19px">'+esc(c.title)+'</h2><span>'+posts.length+' posts</span></div>'+(posts.length?'<div class="panel">'+posts.map(v=>videoCard(v,true)).join("")+'</div>':'<div class="empty">No submissions for this offer yet.</div>')}).join("")+'<div class="notice">Seeded analytics are demo data, last updated Nov 10, 2026. Newly submitted videos say Stats pending. Restaurant-reported customer visits are tracked on campaign results, not added to video views.</div></section>'}
function formModal(title,body,submit,handler){$("#modalTitle").textContent=title;$("#modalContent").innerHTML='<form id="dialogForm">'+body+'<button type="submit" class="button full">'+submit+'</button></form>';$("#modal").showModal();$("#dialogForm").addEventListener("submit",e=>{e.preventDefault();handler(new FormData(e.currentTarget))})}
function closeModal(){if(typeof qrScanning!=="undefined"&&qrScanning){qrScanning=false;if(qrStream){qrStream.getTracks().forEach(t=>t.stop());qrStream=null;}}$("#modal").close()}
function userJoin(){const s=me();formModal("Join as a creator",'<p class="small muted">Anyone can apply. No minimum followers. Two helpful local posts, or a starter sample.</p>'+field("school","Your school",s.school)+field("handle","Social handle",s.handle)+field("post1","Local post link #1",s.links[0]||"","url")+field("post2","Local post link #2",s.links[1]||"","url")+'<p class="help">New creators can join without a follower minimum. Add two useful local post links for review.</p>',"Save application",data=>{const school=String(data.get("school")||"").trim(),handle=String(data.get("handle")||"").trim(),links=["post1","post2"].map(k=>String(data.get(k)||"").trim());if(!school||!handle){toast("Add your school and handle.");return}if(links.some(x=>x&&!validUrl(x))){toast("Enter valid http(s) post links.");return}s.school=school;s.handle=handle;s.links=links.filter(Boolean);if(s.links.length<2){toast("Saved. Add two posts or complete the starter brief for review.");}else toast("Creator application saved for review.");persist();closeModal();render()})}
function editProfile(){const s=me();formModal("Your creator profile",field("name","Name",s.name)+field("school","School",s.school)+field("handle","Social handle",s.handle),"Save profile",d=>{const name=String(d.get("name")||"").trim(),school=String(d.get("school")||"").trim(),handle=String(d.get("handle")||"").trim();if(!name||!school||!handle)return toast("Complete all fields.");Object.assign(s,{name,school,handle});persist();closeModal();render();toast("Profile updated.")})}
function starter(){formModal("Starter brief",'<p class="tagline">“Where would you send a friend for lunch under $15 in Providence?”</p><p class="small muted">Share a useful sample that names a location, approximate price, and what you actually recommend.</p>'+field("link","Your sample video link","","url"),"Submit sample",d=>{const link=String(d.get("link")||"").trim();if(!validUrl(link))return toast("Enter a valid public video URL.");state.starterStatus="submitted";persist();closeModal();render();toast("Starter sample submitted for demo review.")})}
function field(name,label,value="",type="text"){return '<div class="form-group"><label class="label" for="field-'+name+'">'+label+'</label><input class="field" id="field-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" required maxlength="250"></div>'}
function validUrl(url){try{const u=new URL(url);return (u.protocol==="https:"||u.protocol==="http:")&&!!u.hostname.includes(".")}catch{return false}}
function validSocialLink(url){if(!validUrl(url))return false;const host=new URL(url).hostname.toLowerCase();return host==="tiktok.com"||host.endsWith(".tiktok.com")||host==="instagram.com"||host.endsWith(".instagram.com")}
function submitPost(id,data){const a=state.claims.find(x=>x.id===id);if(!a||a.studentId!==state.activeStudent||videoForClaim(id))return toast("This visit is already submitted.");if(!a.redeemedAt)return toast("Redeem your QR at the restaurant before submitting.");const url=String(data.get("url")||"").trim();if(!validSocialLink(url))return toast("Use a public TikTok or Instagram URL.");const host=new URL(url).hostname.toLowerCase(),plat=host.includes("tiktok")?"TikTok":"Instagram Reel",c=campaign(a.campaignId);state.videos.push({id:uid(),claimId:id,studentId:state.activeStudent,campaignId:c.id,url,title:c.title+" · "+me().name,platform:plat,date:new Date().toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}),image:c.image,views:null,likes:null,comments:null,saves:null,updated:null,demo:false});a.status="posted";state.overdueSimulation=false;persist();goTab("content");toast("Posted! Your video is now in your portfolio and the restaurant dashboard.")}
function createOffer(data){const title=String(data.get("title")||"").trim(),name=String(data.get("business")||"").trim(),neighborhood=String(data.get("neighborhood")||"Elmhurst").trim(),reward=String(data.get("reward")||"").trim(),window=String(data.get("window")||"").trim(),post=String(data.get("post")||"").trim(),spots=Number(data.get("spots")),hook=String(data.get("hook")||"").trim(),shots=String(data.get("shots")||"").trim(),talkingPoints=String(data.get("talkingPoints")||"").trim(),creativeFreedom=String(data.get("creativeFreedom")||"").trim(),videoFormat=String(data.get("videoFormat")||"Either"),postingTime=String(data.get("postingTime")||"Within 48 hours after visit");if(!title||!name||!reward||!window||!post||!Number.isInteger(spots)||spots!==3||!hook||!shots||!talkingPoints)return toast("Please complete the offer details.");let b=state.businesses.find(x=>x.name.toLowerCase()===name.toLowerCase());if(!b){b={id:uid(),name,neighborhood,photo:PHOTO.lunch};state.businesses.push(b)}const c={id:uid(),businessId:b.id,title,neighborhood,comp:"visit",reward,spots,window,deadline:postingTime,post,hook,shots,talkingPoints,creativeFreedom,videoFormat,brief:"Hook: "+hook+". Shots: "+shots+". Important details: "+talkingPoints+". Creative guidance: "+(creativeFreedom||"Honest review.")+". Clearly disclose the complimentary visit.",description:"A new local opportunity created for the FuseGenerated demo.",image:PHOTO.lunch,price:reward,status:"open",visitBy:"Dec 15, 2026"};state.campaigns.unshift(c);state.customerVisits[c.id]=0;state.offerComp="visit";persist();goTab("overview");goDetail("campaign",c.id);toast("Demo offer published! Switch to Creator to claim it.")}
function showSamples(id){const s=student(id);$("#modalTitle").textContent=s.name+" · local samples";$("#modalContent").innerHTML='<div class="stack"><div class="video-preview" style="height:170px">'+img(id==="maya"?PHOTO.coffee:PHOTO.city,"Local preview")+'</div><p class="small muted">Sample local post 1 · '+esc(s.handle)+'</p><div class="video-preview" style="height:170px">'+img(id==="maya"?PHOTO.toast:PHOTO.bowl,"Local preview")+'</div><p class="small muted">Sample local post 2 · '+esc(s.handle)+'</p><p class="fine-print">Photo previews are illustrative demo placeholders; real uploaded creator posts are not fetched.</p></div>';$("#modal").showModal()}
function copyInvite(id){const a=state.claims.find(x=>x.id===id),c=campaign(a.campaignId);const msg="I claimed a FuseGenerated spot for "+c.title+" at "+business(c.businessId).name+". Want to come? Your own spot is covered, and you post your own original video. Demo invite: fusegenerated.app/invite/"+c.id;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(msg).then(()=>toast("Invite text copied.")).catch(()=>toast(msg));else toast("Invite preview available below.");}
async function updateTikTokBadge(){try{const r=await fetch("/api/tiktok/status",{credentials:"same-origin"});const j=await r.json();const badge=$("#tiktokBadge");if(badge){badge.textContent=j.connected?"Connected with TikTok":j.configured?"Ready to connect":"Integration setup required";badge.className="status "+(j.connected?"good":"waiting");}}catch{}}
async function connectTikTok(){try{const r=await fetch("/api/tiktok/status",{credentials:"same-origin"});const j=await r.json();if(!j.configured){return formModal("TikTok connection setup",'<p class="small muted">FuseGenerated needs TikTok Login Kit approval and secure developer credentials before real authorization can work. The profile @nevedog101 is set, but typing a handle does not connect your TikTok account.</p><p class="small muted">Until configured, use your real TikTok video link in My visits. The video will appear in FuseGenerated immediately.</p>',"Got it",()=>closeModal());}window.location.assign("/api/tiktok/start");}catch{toast("TikTok connection is not available yet.");}}
let authorizedTikToks=[];
function attachTikTokVideo(id){
 const v=authorizedTikToks.find(x=>String(x.id)===String(id));if(!v)return toast("Load TikTok videos again.");
 const pending=state.claims.filter(a=>a.studentId===state.activeStudent&&campaign(a.campaignId)?.status==="open"&&!videoForClaim(a.id)&&a.status!=="invited"&&!!a.redeemedAt);
 if(!pending.length)return toast("Claim a restaurant visit first.");
 const select='<div class="form-group"><label class="label" for="field-visit">Choose restaurant visit</label><select id="field-visit" class="field" name="claim" required>'+pending.map(a=>'<option value="'+esc(a.id)+'">'+esc(business(campaign(a.campaignId).businessId).name)+' · '+esc(campaign(a.campaignId).title)+'</option>').join("")+'</select></div>';
 formModal("Use TikTok for a visit",'<p class="small muted">'+esc(v.title||"TikTok video")+'</p><p class="small muted">Submit this original post to the restaurant. Its TikTok metrics will appear in My content.</p>'+select,"Submit to restaurant",data=>{
 const claimId=String(data.get("claim")||""),a=pending.find(x=>x.id===claimId);if(!a||!v.share_url)return toast("Choose a valid visit.");
 if(state.videos.some(x=>x.claimId===claimId))return toast("Already submitted.");
 state.videos.push({id:uid(),claimId:a.id,studentId:state.activeStudent,campaignId:a.campaignId,url:v.share_url,title:v.title||campaign(a.campaignId).title,platform:"TikTok",date:v.create_time?new Date(Number(v.create_time)*1000).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}):"Recently posted",image:v.cover_image_url||campaign(a.campaignId).image,views:v.view_count??null,likes:v.like_count??null,comments:v.comment_count??null,saves:null,updated:"Synced from TikTok",demo:false});
 a.status="posted";persist();closeModal();goTab("content");toast("TikTok linked to your restaurant visit.");
 });
}
async function loadTikTokFeed(){const el=$("#tiktokFeed");if(!el)return;try{const r=await fetch("/api/tiktok/videos",{credentials:"same-origin"});if(r.status===401){el.innerHTML='<p class="small muted">Not connected yet. Authorize TikTok from Profile, or paste your post link in My visits.</p>';return;}if(!r.ok)throw Error("TikTok is unavailable");const json=await r.json();const videos=Array.isArray(json.videos)?json.videos:[];authorizedTikToks=videos;el.innerHTML=videos.length?videos.slice(0,12).map(v=>'<div class="video-card"><div class="flex"><div class="video-thumb">'+img(v.cover_image_url||PHOTO.coffee,v.title||"TikTok video")+'</div><div><h4>'+esc(v.title||"My TikTok")+'</h4><p class="tiny-muted">'+fmt(v.view_count||0)+' views · '+fmt(v.like_count||0)+' likes</p><a href="'+esc(v.share_url)+'" target="_blank" rel="noopener noreferrer" class="button text">Watch on TikTok ↗</a>'+btn("Use for a visit","attach-tiktok",v.id,"button secondary tiny")+'</div></div></div>').join(""):'<p class="small muted">No public TikTok uploads found on this connected account.</p>'; }catch{el.innerHTML='<p class="small muted">TikTok videos are unavailable right now. You can still submit a video URL in My visits.</p>';}}
function doAction(action,id){switch(action){
case"video-filter":state.tiktokFeed=id;persist();render();return;
case"add-tiktok":$("#modalTitle").textContent="Add a TikTok to Fuse";$("#modalContent").innerHTML=videoForm();$("#modal").showModal();return;
case"delete-tiktok":state.tiktokPosts=state.tiktokPosts.filter(v=>v.id!==id);persist();render();toast("Video removed from this browser.");return;
case"show-explore":return goTab("explore");
case"content-section":state.contentSection=id;render();return;
case"friend-section":state.friendsSection=id;render();return;
case"view-friend":return goDetail("friend-profile",id);
case"toggle-friend":state.friends=state.friends.includes(id)?state.friends.filter(x=>x!==id):[...state.friends,id];persist();render();return;
case"scan-qr":return scanQR();
case"stop-qr":return stopQrScan();
case"toggle-map":state.mapVisible=!state.mapVisible;render();return;
case"copy-referral":{const copy="Join FuseGenerated for covered Providence creator visits! My demo code: "+state.referralCode;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(copy).then(()=>toast("Invite copied")).catch(()=>toast(copy));else toast(copy);return;}
case"referral-join":if(!state.referrals.includes("leo")){state.referrals.push("leo");persist();toast("Leo joined your demo invite.");}else toast("Already joined in demo.");render();return;
case"switch-student":state.activeStudent=state.activeStudent==="maya"?"leo":"maya";persist();render();return toast("Now previewing "+me().name);
case"claim-with-friend":return openDuoClaim(id);
case"accept-tagged":{const a=state.claims.find(x=>x.id===id&&x.studentId===state.activeStudent);if(!a||a.status!=="invited")return;a.status="claimed";persist();render();toast("Invite accepted. Each creator posts separately.");return;}
case"connect-tiktok":return connectTikTok();
case"attach-tiktok":return attachTikTokVideo(id);
case"qr":return goDetail("qr",id);
case"offer":return goDetail("offer",id);
case"back":if(state.detail?.type==="qr")return goTab("content");if(state.detail?.type==="offer")return goTab("explore");if(state.detail?.type==="friend")return goDetail("claimed",id);if(state.detail?.type==="claimed")return goTab("content");if(state.detail?.type==="restaurant")return goTab("content");if(state.detail?.type==="video")return goTab(state.role==="student"?"content":"videos");return goTab(state.role==="student"?"explore":"overview");
case"claim":{const a=claim(id);if(a)goDetail("claimed",a.id);return}
case"friend":return goDetail("friend",id);
case"accept-friend":{const original=state.claims.find(x=>x.id===id);if(!original)return;const a=claim(original.campaignId,"leo");if(!a)return;state.activeStudent="leo";persist();goTab("visits");toast("Leo accepted. Both spots are now claimed.");return}
case"copy-invite":return copyInvite(id);
case"visits":state.contentSection="visits";return goTab("content");
case"explore":case"forYou":case"friends":case"content":case"profile":case"referrals":case"overview":case"create":case"creators":case"videos":return goTab(action);
case"restaurant":return goDetail("restaurant",id);
case"video":return goDetail("video",id);
case"campaign":return goDetail("campaign",id);
case"plus-one":state.customerVisits[id]=(state.customerVisits[id]||0)+1;persist();render();return toast("Customer visit reported.");
case"set-comp":state.offerComp=id;document.querySelectorAll(".choice").forEach(b=>b.classList.toggle("selected",b.dataset.id===id));return;
case"switch-student":state.activeStudent=state.activeStudent==="maya"?"leo":"maya";persist();render();return toast("Now demoing as "+me().name+".");
case"join":return userJoin();
case"edit-profile":return editProfile();
case"starter":return starter();
case"samples":return showSamples(id);
case"approve":{const a=state.claims.find(x=>x.id===id);if(!a)return;a.review="approved";student(a.studentId).approved=true;persist();render();return toast("Creator approved for this demo.")}
case"mark-visited":{const a=state.claims.find(x=>x.id===id);if(a&&a.studentId===state.activeStudent&&!videoForClaim(id)){a.status="visited";persist();render();toast("Visit marked complete. Don't forget your video.");}return;}
case"simulate-overdue":{let a=state.claims.find(x=>x.studentId===state.activeStudent&&campaign(x.campaignId)?.status==="open"&&!videoForClaim(x.id));if(!a)return toast("Claim a new offer first to test the overdue reminder.");a.status="overdue";state.overdueSimulation=true;persist();render();return toast("Overdue reminder activated. New claims are blocked until posting.")}
}}
document.addEventListener("click",e=>{const a=e.target.closest("[data-action],[data-tab]");if(!a)return;if(a.dataset.tab)return goTab(a.dataset.tab);if(a.dataset.action)doAction(a.dataset.action,a.dataset.id)});
document.addEventListener("change",e=>{if(e.target?.id==="businessSelect"){state.selectedBusiness=e.target.value;persist();render();}});
document.addEventListener("input",e=>{if(e.target?.id!=="friendSearch")return;const q=e.target.value.trim().toLowerCase();const chosen=community.filter(x=>(state.friendsSection!=="mine"||state.friends.includes(x.id))&&[x.name,x.handle,x.school,x.area,x.tags].join(" ").toLowerCase().includes(q));const target=$("#friendResults");if(target)target.innerHTML=chosen.length?chosen.map(friendCard).join(""):'<div class="empty">No creators match your search.</div>';});
document.addEventListener("submit",e=>{const form=e.target.closest("[data-form]");if(!form)return;e.preventDefault();if(form.dataset.form==="post")submitPost(form.dataset.id,new FormData(form));if(form.dataset.form==="new-offer")createOffer(new FormData(form));if(form.dataset.form==="redeem")redeemCode(new FormData(form).get("code"));if(form.dataset.form==="add-tiktok"){addTikTok(new FormData(form));closeModal()}if(form.dataset.form==="espresso-video")submitPersonalVideo(new FormData(form))});
$("#roleSwitch").addEventListener("click",()=>{state.role=state.role==="student"?"business":"student";state.detail=null;state.tab=state.role==="student"?"explore":"overview";persist();render();$("#content").scrollTop=0});
$("#resetDemo").addEventListener("click",()=>{if(!confirm("Reset all demo claims, submissions, and offers?"))return;state=seed();persist();render();$("#content").scrollTop=0;toast("Demo reset to the starting state.")});
$("#closeModal").addEventListener("click",closeModal);
$("#modal").addEventListener("click",e=>{if(e.target===$("#modal"))closeModal()});
render();
